import os
import time
import six
import logging
from moler.device import DeviceFactory
from taf.internal.robot_typecasts import time_to_seconds
from taf.converters.sherpa.interface import sherpa
from taf.rfrl.bts.devices.generic_bts import login_logout_GUI, login_logout
from taf.rfrl.bts.devices.du.logs_collecting.basic_logs import GenericLog
from taf.rfrl.bts.helpers.singleton import Singleton
from taf.rfrl.utilities import tl_config
from taf.rfrl.utilities.tl_config import load_moler_configuration_from_tl
from taf.rfrl.utilities.test_config import get_log_path


class GenericSherpaCollector(GenericLog):
    """Logs collecting keywords for eNB and gNB"""

    @login_logout_GUI
    def start_streaming_sherpa_logs_via_gui(self, cells_list=[], bts_id=0, timeout=60, du_id=0):
        """
        Start streaming Sherpa logs.
        :param cells_list: list of cells for LO and PS tracing. If empty all available cells are traced.
        :param timeout: timeout for waiting for single sherpa log collection. Default: 60s.
        :param bts_id: BTS(eNB/gNB) id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return: None
        """
        timeout = time_to_seconds(timeout)
        gui_alias = self.gui_alias.format(bts_id, du_id)
        status_l2hi = self.gui_coam.start_l2_hi_pdcp_sherpa_trace_and_return_result(timeout=timeout,
                                                                                    sbts=gui_alias)
        logging.info("Start L2 HI PDCP sherpa trace status: {}".format(status_l2hi))
        status_l2lo = self.gui_coam.start_l2_lo_sherpa_trace_and_return_result(cells_list=cells_list, timeout=timeout,
                                                                               sbts=gui_alias)
        logging.info("Start L2 LO sherpa trace status: {}".format(status_l2lo))
        status_l2ps = self.gui_coam.start_l2_ps_sherpa_trace_and_return_result(cells_list=cells_list, timeout=timeout,
                                                                               sbts=gui_alias)
        logging.info("Start L2 PS sherpa trace status: {}".format(status_l2ps))

    @login_logout_GUI
    def stop_streaming_sherpa_logs_via_gui(self, bts_id=0, du_id=0):
        """
        Stop streaming Sherpa logs.
        :param bts_id: BTS(eNB/gNB) id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return: None
        """
        gui_alias = self.gui_alias.format(bts_id, du_id)
        self.gui_coam.stop_sherpa_trace(uplane_sherpa_name="L2-HI", source="PDCP", sbts=gui_alias)
        self.gui_coam.stop_sherpa_trace(uplane_sherpa_name="L2-LO", sbts=gui_alias)
        self.gui_coam.stop_sherpa_trace(uplane_sherpa_name="L2-PS", sbts=gui_alias)

    @load_moler_configuration_from_tl()
    @login_logout
    def start_streaming_sherpa_logs(self, timeout=60, bts_id=0, du_id=0, source_ip=None, dscp="10",
                                    destination_ip=None, destination_port='5678'):
        """
        Start streaming Sherpa logs.
        :param str source_ip: eg. "10.12.10.102"
        :param Union[int,str] dscp: eg. 1
        :param str destination_ip: eg. "10.12.10.102"
        :param Union[int,str] destination_port: eg. 1025
        :param timeout: timeout for waiting for single start sherpa log collection. Default: 60s.
        :param bts_id: BTS(eNB/gNB) id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return: None
        """
        trace_type = "Sherpa"
        if source_ip is None:
            source_ip = tl_config.get_oam_ip_address(bts_id=bts_id, du_id=du_id)
        if destination_ip is None:
            ws_du_device = DeviceFactory.get_device(name=self.ws_du_alias.format(bts_id, du_id))
            ip_addresses = ws_du_device.get_cmd(cmd_name='ip_addr')()
            destination_ip = ip_addresses['eth0']['IPV4'][0]['IP']

        conn = self.rest_alias.format(bts_id, du_id)
        timeout = time_to_seconds(timeout)
        status_l2hi = self.admin.start_uplane_l2_trace(source_ip=source_ip, dscp=dscp, destination_ip=destination_ip,
                                                       destination_port=destination_port, up_sw="L2HiPdcp",
                                                       timeout=timeout, trace_type=trace_type, connection=conn)
        logging.info("Start L2 HI PDCP sherpa trace status: {}".format(status_l2hi))

        status_l2lo = self.admin.start_uplane_l2_trace(source_ip=source_ip, dscp=dscp, destination_ip=destination_ip,
                                                       destination_port=destination_port, up_sw="L2Lo",
                                                       timeout=timeout, trace_type=trace_type, connection=conn)
        logging.info("Start L2 LO sherpa trace status: {}".format(status_l2lo))

        status_l2ps = self.admin.start_uplane_l2_trace(source_ip=source_ip, dscp=dscp, destination_ip=destination_ip,
                                                       destination_port=destination_port, up_sw="L2Ps",
                                                       timeout=timeout, trace_type=trace_type, connection=conn)
        logging.info("Start L2 PS sherpa trace status: {}".format(status_l2ps))

    @login_logout
    def stop_streaming_sherpa_logs(self, bts_id=0, du_id=0, timeout=60):
        """
        Stop streaming Sherpa logs.
        :param bts_id: BTS(eNB/gNB) id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param timeout: timeout for waiting for single stop sherpa log collection. Default: 60s.
        :return: None
        """
        trace_type = "Sherpa"
        conn = self.rest_alias.format(bts_id, du_id)
        self.admin.stop_uplane_l2_trace(up_sw="L2HiPdcp", trace_type=trace_type, timeout=timeout, connection=conn)
        self.admin.stop_uplane_l2_trace(up_sw="L2Lo", trace_type=trace_type, timeout=timeout, connection=conn)
        self.admin.stop_uplane_l2_trace(up_sw="L2Ps", trace_type=trace_type, timeout=timeout, connection=conn)

    def convert_sherpa_pcap_log_to_csv(self, path_to_pcap, output_dir, bts_id=0, du_id=0, common_unit_id=0):
        """
        Generate set of .csv files from sherpa .pcap log file
        :param path_to_pcap: local path to .pcap file
        :param output_dir: local directory where csv files are stored
        :param bts_id: BTS(eNB/gNB) id - related to Test Line configuration
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param common_unit_id: Id of CommonUnit - related to Test Line configuration
        :return: None
        """
        sherpa_converter = sherpa()
        ws_credentials = tl_config.get_bts_ws_credentials(int(bts_id), int(du_id), int(common_unit_id), self.bts_type)
        sherpa_converter.create_sherpa_converter(name="sherpa", executor=ws_credentials,
                                                 file_path_pattern=path_to_pcap, output_path=output_dir)
        sherpa_converter.setup(alias="sherpa")
        sherpa_converter.convert(name="sherpa")
        sherpa_converter.teardown(alias="sherpa")

    def setup_sherpa_tcpdump_collector(self, options="", bts_id=0, du_id=0, common_unit_id=0):
        """
        Setup tcpdump collector - using taf.collectors
        :param options: (optional) tcpdump options (except -w), default: empty string
        :param bts_id: BTS(eNB/gNB) id - related to Test Line configuration
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param common_unit_id: Id of CommonUnit
        :return: None
        """

        core = self._try_to_get_robot_builtin_instance('core', 'taf.collectors.core')
        tcpdump = self._try_to_get_robot_builtin_instance('tcpdump', 'taf.collectors.tcpdump')

        name = "sherpa_tcpdump_{}".format(self._get_log_prefix(bts_id, du_id))
        ws_credentials = tl_config.get_bts_ws_credentials(int(bts_id), int(du_id), int(common_unit_id), self.bts_type)

        tcpdump.create_tcpdump_collector(name=name, options=options, executor=ws_credentials)
        tcpdump.set_suite_alias(alias=name)
        core.setup_collectors(names=name)

    def start_collecting_sherpa_tcpdump(self, options="", bts_id=0, du_id=0, common_unit_id=0):
        """
        Start collecting tcpdump - using taf.collectors
        :param options: (optional) tcpdump options (except for -w), default: empty string
        :param bts_id: BTS(eNB/gNB) id - related to Test Line configuration
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param common_unit_id: Id of CommonUnit
        :return: None
        """
        core = self._try_to_get_robot_builtin_instance('core', 'taf.collectors.core')
        name = "sherpa_tcpdump_{}".format(self._get_log_prefix(bts_id, du_id))
        if not core.get_alias_value(alias=name):
            self.setup_sherpa_tcpdump_collector(options, bts_id, du_id, common_unit_id)
        core.start_collectors(names=name)

    @load_moler_configuration_from_tl()
    def stop_collecting_sherpa_tcpdump(self, bts_id=0, du_id=0, log_dir=None):
        """
        Stop collecting tcpdump - using taf.collectors
        :param bts_id: BTS(eNB/gNB) id - related to Test Line configuration
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param log_dir: Directory where tcpdump will be collected. If None default robot log path is used.
        :return: path to tcpdump pcap file
        """
        core = self._try_to_get_robot_builtin_instance('core', 'taf.collectors.core')
        name = "sherpa_tcpdump_{}".format(self._get_log_prefix(bts_id, du_id))
        tcpdump_collector = core.get_alias_value(alias=name)
        if log_dir is None:
            log_dir = os.path.join(get_log_path(), "sherpa", "tcpdump_{}".format(time.time()))
        pid = tcpdump_collector._pid
        if pid is not None:
            ws_du_device = DeviceFactory.get_device(name=self.ws_du_alias.format(bts_id, du_id))

            ps_result = ws_du_device.get_cmd(cmd_name='ps', cmd_params={'options': '-p {}'.format(pid)})()
            if ps_result:
                core.stop_collectors(names=name)
            else:
                logging.debug("Process [{}] does not exists - skipping stop collector".format(pid))
                tcpdump_collector._is_started = False
        core.collect_collectors(names=name, target_dir=log_dir)
        log_path = os.path.join(log_dir, name)
        return log_path

    def teardown_sherpa_tcpdump_collector(self, bts_id=0, du_id=0):
        """
        Teardown tcpdump collector - using taf.collectors
        :param bts_id: BTS(eNB/gNB) id - related to Test Line configuration
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return: None
        """
        core = self._try_to_get_robot_builtin_instance('core', 'taf.collectors.core')
        name = "sherpa_tcpdump_{}".format(self._get_log_prefix(bts_id, du_id))

        core.teardown_collectors(names=name)


@six.add_metaclass(Singleton)
class EnbSherpaCollector(GenericSherpaCollector):
    """Class contains sherpa logs collecting keywords for eNB"""

    bts_type = 'ENB'

    def __init__(self):
        """
        Constructor of Enb class.

        """

        super(EnbSherpaCollector, self).__init__(bts_type=EnbSherpaCollector.bts_type)


@six.add_metaclass(Singleton)
class GnbSherpaCollector(GenericSherpaCollector):
    """Class contains sherpa collecting keywords for gNB"""

    bts_type = 'GNB'

    def __init__(self):
        """
        Constructor of Gnb class.

        """
        super(GnbSherpaCollector, self).__init__(bts_type=GnbSherpaCollector.bts_type)
